def require_ref(r, sline, steps, sid, quiet=False):
    if r not in steps:
        if not quiet:
            fail(f"step {sid}: reference to unknown step '{r}'")
        return False
    if steps[r]["line"] >= sline:
        if not quiet:
            fail(f"step {sid}: forward reference to '{r}'")
        return False
    return True


def norm(s):
    s = BY_RE.sub(' ', s).strip().rstrip('.').strip()
    s = re.sub(r'^Goal:\s*', '', s)
    s = re.sub(r'^THEOREM\s+\w+\s*:\s*', '', s)
    s = re.sub(r'^OBL-\d+(\s*\([^)]*\))?:\s*', '', s)
    s = re.sub(r'^\|-\s*', '', s)
    s = re.sub(r'\s*:\s*(Z|List|Prop)\b', '', s)
    s = re.sub(r'defined\([^)]*\)\s*/\\\s*', '', s)
    s = re.sub(r'\s+', ' ', s).strip()
    q, rest = [], s
    while True:
        m = re.match(r'^forall\s+(\w+)\.\s*', rest)
        if not m:
            break
        q.append(m.group(1))
        rest = rest[m.end():]
    return sorted(q), rest


def parse_obligations(path):
    text = open(path).read()
    blocks, cur = {}, None
    for line in text.splitlines():
        m = OBL_HEADER_RE.match(line)
        if m:
            cur = int(m.group(1))
            blocks[cur] = []
            continue
        if cur is not None and line.lstrip().startswith('---'):
            cur = None
        elif cur is not None:
            blocks[cur].append(line)
    stmts = {}
    for n, lines in blocks.items():
        collect, keep = False, []
        for line in lines:
            st = line.strip()
            if not collect:
                if st.startswith('Statement'):
                    collect = True
                continue
            if not st or re.match(r'^(Measure|Strategy|Key lemma|Status|where|'
                                  r'Note|These|Needed|Not required|Together|'
                                  r'Justifies|Proof by|\(a\))', st):
                break
            keep.append(st)
        stmts[n] = ' '.join(keep)
    return stmts


def main():
    global lemma_final
    proof_path = sys.argv[1] if len(sys.argv) > 1 else 'proof.txt'
    obl_path = sys.argv[2] if len(sys.argv) > 2 else 'obligations.txt'
    text = open(proof_path).read()

    if re.search(r'\bsorry\b', text, re.I):
        fail("certificate contains 'sorry'")
    if re.search(r'\badmit\b', text, re.I):
        fail("certificate contains 'admit'")

