    if r not in steps:
        if not quiet:
            fail(f"step {sid}: reference to unknown step '{r}'")
        return False
    if steps[r]["line"] >= sline:
        if not quiet:
            fail(f"step {sid}: forward reference to '{r}'")
        return False
    return True


